use std::fs
use std::strings

fn digit_val(c: char) -> int {
    let n = c as int
    if n >= 48 && n <= 57 {
        n - 48
    } else if n >= 65 && n <= 90 {
        n - 55
    } else {
        n - 87
    }
}

fn main() {
    let t = fs::read_to_string("/dev/stdin").unwrap_or("")
    let digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    let table = digits.chars().collect::<Vec<char>>()
    for l in t.lines() {
        let parts = strings::split_whitespace(l)
        if parts.len() < 3 {
            continue
        }
        let from: int = parts[1].parse::<int>().unwrap_or(10)
        let to: int = parts[2].parse::<int>().unwrap_or(10)
        let mut v: int = 0
        for c in parts[0].chars() {
            v = v * from + digit_val(c)
        }
        if v == 0 {
            println("0")
            continue
        }
        let mut out: Vec<char> = []
        while v > 0 {
            out.push(table[(v % to) as usize])
            v = v / to
        }
        let mut s = ""
        let mut i: int = out.len() as int - 1
        while i >= 0 {
            s = s + out[i as usize].to_string()
            i -= 1
        }
        println("${s}")
    }
}

